#include <bits/stdc++.h>
using namespace std;

class Solution {public:int countLatticePoints(vector<vector<int>>& circles){set<pair<int,int>> p;for(auto &c:circles){int x=c[0],y=c[1],r=c[2];for(int i=x-r;i<=x+r;++i)for(int j=y-r;j<=y+r;++j)if((i-x)*(i-x)+(j-y)*(j-y)<=r*r)p.insert({i,j});}return p.size();} };
